begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
select ok(not has_table_privilege('anon','academy.primary_documents','select'),'Primary documents remain private');
select ok(not has_table_privilege('authenticated','academy.primary_documents','insert'),'No direct client primary-document provenance writes');
select ok(not has_table_privilege('authenticated','academy.dossiers','insert'),'No direct client dossier writes');
select ok(not has_table_privilege('authenticated','academy.claims','update'),'No client status=verified bypass');
select ok(not has_table_privilege('authenticated','academy.scientific_reviews','insert'),'Reviews only through checked command');
select ok(not has_table_privilege('authenticated','academy.editorial_briefs','insert'),'Briefs only through reviewed gate');
select ok(not has_function_privilege('authenticated','academy.save_agent_dossier(uuid,jsonb,integer,uuid)','execute'),'Editor cannot impersonate agent to bypass self-review');
select ok(not has_function_privilege('authenticated','academy.save_operator_pdf(uuid,uuid,text,text,jsonb,text,jsonb,text)','execute'),'Only trusted worker can attest parsed operator PDF');
select ok(not has_function_privilege('authenticated','academy.complete_primary_pdf(uuid,uuid,text,jsonb)','execute'),'Only worker can finish PDF extraction');
select ok(not has_function_privilege('service_role','academy.review_scientific_claim(uuid,text,text,text,integer,integer,uuid)','execute'),'Worker cannot manufacture a human scientific review');
select ok(not has_function_privilege('service_role','academy.approve_research_dossier(uuid,text,uuid[],text,uuid)','execute'),'Worker cannot manufacture dossier approval');
select ok(not has_table_privilege('service_role','academy.scientific_reviews','insert'),'Worker cannot bypass human review RPC via direct table insert');
select ok(not has_table_privilege('service_role','academy.editorial_briefs','insert'),'Worker cannot insert a reviewed brief outside the gate');
select ok(has_function_privilege('authenticated','academy.review_scientific_claim(uuid,text,text,text,integer,integer,uuid)','execute'),'Scoped human review command available to checked members');
select ok(not has_function_privilege('anon','academy.research_review_state(uuid)','execute'),'Anonymous cannot inspect dossier state');
insert into auth.users(id,email) values('12000000-0000-4000-8000-000000000001','research-reviewer@example.test'),('12000000-0000-4000-8000-000000000002','research-outsider@example.test');
insert into academy.editor_members(user_id,role) values('12000000-0000-4000-8000-000000000001','reviewer');
set local role authenticated;
select set_config('request.jwt.claim.sub','12000000-0000-4000-8000-000000000001',true);
select throws_ok($$select academy.save_primary_text(gen_random_uuid(),gen_random_uuid(),'v1','full_text','https://arxiv.org/abs/9912.00001','{}','x')$$,'42501','Editor role required','Scientific reviewer cannot intake/edit documents');
select throws_ok($$select academy.save_research_dossier(gen_random_uuid(),'{}',0,gen_random_uuid())$$,'42501','Editor role required','Scientific reviewer cannot edit dossier');
select throws_ok($$select academy.create_editorial_brief(gen_random_uuid(),true,'x')$$,'42501','Editor role required','Scientific reviewer cannot generate briefs');
select set_config('request.jwt.claim.sub','12000000-0000-4000-8000-000000000002',true);
select is((select count(*) from academy.primary_documents),0::bigint,'Outsider reads no documents');
select is((select count(*) from academy.scientific_reviews),0::bigint,'Outsider reads no scientific reviews');
select throws_ok($$select academy.review_scientific_claim(gen_random_uuid(),'accept','Sufficient test reason',null,0,0,gen_random_uuid())$$,'42501','Editorial membership required','Outsider cannot write a review');
select throws_ok($$select academy.approve_research_dossier(gen_random_uuid(),'x','{}','Sufficient test reason',gen_random_uuid())$$,'42501','Editorial membership required','Outsider cannot approve dossier');
set local role service_role;
select throws_ok($$insert into academy.editorial_decisions(story_id,actor_type,actor_id,decision,reason,policy_version,dossier_id) values(gen_random_uuid(),'human','12000000-0000-4000-8000-000000000001','approve','Forged worker approval','scientific-dossier/1',gen_random_uuid())$$,'42501','Worker cannot insert human scientific decisions','Legacy service write grant cannot forge a scientific whole-dossier approval');
insert into academy.stories(id,slug,title_en) values('12000000-0000-4000-8000-000000000010','scientific-approval-laundering-fixture','Synthetic legacy decision guard');
insert into academy.editorial_decisions(story_id,actor_type,actor_id,decision,reason,policy_version) values('12000000-0000-4000-8000-000000000010','agent','synthetic-worker','hold','Synthetic legacy worker decision','selection/1');
select throws_ok($$update academy.editorial_decisions set dossier_id=gen_random_uuid(),actor_type='human',actor_id='12000000-0000-4000-8000-000000000001',decision='approve',policy_version='scientific-dossier/1' where story_id='12000000-0000-4000-8000-000000000010'$$,'42501','Worker cannot insert human scientific decisions','Worker cannot relabel a legacy row into a human scientific approval');
select * from finish();
rollback;
